// Fail fast, before any backup work, on the settings that ship as placeholders.
//
// A placeholder that LOOKS valid is worse than a blank one. you@example.com is a
// reserved domain: mail servers accept it and discard it, so the run goes green,
// SMTP returns 250 OK, and the report never arrives - with nothing anywhere
// saying why. Stopping here costs one failed run and explains itself.
const s = $input.first().json;
const problems = [];

const email = String(s.notify_email || '').trim();
if (!email) {
  problems.push('notify_email is empty. Set it to the address the report should go to.');
} else if (email.toLowerCase() === 'you@example.com') {
  problems.push('notify_email is still the placeholder you@example.com. Set it to your own address - '
    + 'that domain is reserved, so mail servers accept the message and throw it away. You would get a '
    + 'successful run and no email.');
}

const bucket = String(s.s3_bucket || '').trim();
if (!bucket) {
  problems.push('s3_bucket is empty. Set it to the S3 bucket the archives should go to.');
} else if (bucket.toLowerCase() === 'your-backup-bucket') {
  problems.push('s3_bucket is still the placeholder your-backup-bucket. Set it to your own bucket.');
}

const prefix = String(s.s3_prefix || '').trim();
if (!prefix) {
  problems.push('s3_prefix is empty. Retention lists and deletes everything under this '
    + 'prefix, so an empty one points it at the whole bucket. Set it to a folder used '
    + 'only by these backups.');
} else if (prefix.startsWith('/') || prefix.endsWith('/')) {
  problems.push('s3_prefix must not start or end with a slash - the workflow adds its own. '
    + 'A doubled slash lists nothing, so backups would upload while retention silently '
    + 'stopped working.');
}

const days = Number(s.retention_days);
if (!Number.isFinite(days) || days < 1) {
  problems.push('retention_days must be a whole number of days, 1 or more.');
}

if (problems.length) {
  throw new Error('Open the "Set Backup Parameters" node and fix:\n  - ' + problems.join('\n  - '));
}
return $input.all();

// Keep anything inside the retention window; pass on the rest for deletion.
// The cutoff is computed once, not per item, so a long run cannot straddle
// midnight and delete inconsistently.
const days = Number($('Set Backup Parameters').first().json.retention_days);
if (!Number.isFinite(days) || days < 1) {
  throw new Error('retention_days must be a whole number of days, 1 or more');
}
const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
const expired = [];
for (const item of $input.all()) {
  const key = item.json.Key;
  const modified = Date.parse(item.json.LastModified);
  if (!key || key.endsWith('/') || !Number.isFinite(modified)) continue;
  if (modified < cutoff) expired.push({ json: { key, lastModified: item.json.LastModified } });
}
// ALWAYS emit at least one item. A node that returns nothing stops the branch,
// and the branch it would stop is the one carrying the report email. Most
// nights nothing is old enough to delete, so returning [] here meant no report
// on almost every run.
if (expired.length === 0) return [{ json: { nothingExpired: true } }];
return expired;

// Count what actually happened, across EVERY iteration of the loop.
//
// $('node').all() defaults to the LAST run index. Inside a splitInBatches loop
// the node runs once per repository, so a bare .all() reports only the final
// iteration and silently discards the rest. With a single repository the two are
// identical, which is why this survived nine runs before it was noticed.
const results = [];
for (let run = 0; run < 10000; run++) {
  let items;
  try { items = $('Log Repository Backup Status').all(0, run); } catch (e) { break; }
  if (!items || items.length === 0) break;
  results.push(...items);
}

let ok = 0;
const failed = [];
const skipped = [];
for (const item of results) {
  const j = item.json || {};
  if (j.skipped) skipped.push(j.repo || 'unknown');
  else if (j.ok) ok++;
  else failed.push(`${j.repo || 'unknown'}: ${j.error || 'unknown error'}`);
}
// Only count deletions that actually deleted something. The node may not have
// run at all (nothing expired), and a failed delete must not read as a success.
let deleted = 0;
try {
  deleted = $('Delete Expired Backup').all()
    .filter((i) => i.json && !i.json.error && !i.json.nothingExpired).length;
} catch (e) { deleted = 0; }
// The S3 delete node returns {success:true} and does NOT echo the key, so the
// names have to come from the node that chose them. Index i of the delete
// output is the result for index i of this list - an n8n node runs once per
// input item, in order.
const expired = [];
try {
  for (const i of $('Filter Expired Backups').all()) {
    const k = (i.json || {}).key;
    if (k) expired.push(k);
  }
} catch (e) { /* the node never ran - nothing expired */ }
const settings = $('Set Backup Parameters').first().json;
const account = $('Fetch GitHub Account Info').first().json;
const ownerSetting = String(settings.github_owner || '').trim();
const publicOnly = account.type !== 'Organization' && ownerSetting !== '';
const lines = [
  `Account: ${account.login} (${account.type})`,
  `Repositories backed up: ${ok}`,
  `Skipped (empty - no commits to archive): ${skipped.length}`,
  `Failed: ${failed.length}`,
  `Old backups removed: ${deleted}`,
  `Bucket: ${settings.s3_bucket}/${settings.s3_prefix}`,
  `Retention: ${settings.retention_days} days`,
];
if (publicOnly) {
  lines.push('',
    `NOTE: only PUBLIC repositories of ${account.login} were backed up.`,
    'GitHub does not expose another account\'s private repositories.',
    'If this is your own account, clear github_owner in Set Backup Parameters and',
    'your private repositories will be included on the next run.');
}
if (skipped.length) lines.push('', 'Skipped:', ...skipped.map((s) => `  - ${s}`));
if (failed.length) lines.push('', 'Failures:', ...failed.map((f) => `  - ${f}`));
// Name what was destroyed. A count alone made a run that removed 18 backups
// look identical to one that removed none.
if (deleted) {
  lines.push('', 'Removed past retention:');
  for (let i = 0; i < deleted; i++) {
    lines.push(`  ${expired[i] || '(name unavailable)'}`);
  }
  if (deleted !== expired.length) {
    lines.push(`  NOTE: ${expired.length} expired, ${deleted} deletion(s) confirmed.`);
  }
}
return [{ json: {
  account: account.login, accountType: account.type, publicOnly,
  succeeded: ok, skipped: skipped.length, failed: failed.length, deleted,
  subject: `GitHub backup (${account.login}): ${ok} ok, ${skipped.length} skipped, `
    + `${failed.length} failed` + (deleted ? `, ${deleted} removed` : ''),
  body: lines.join('\n'),
} }];

// Single collection point for the loop. Every repository leaves this node with
// one item saying what happened to it, and why if it was not backed up.
//
// Both paths arrive here: a successful upload, and a download that failed on its
// error branch. Reading the error where it happened preserves GitHub's own
// message, instead of the "no binary file 'data'" symptom that S3 reports later
// when it is handed a failed download.
const repoItem = (() => {
  try { return $('Process Each Repository').first().json || {}; }
  catch (e) { return {}; }
})();
const repo = repoItem.name || 'unknown';

// A repository with no commits has nothing to archive. GitHub still returns a
// 302 from /tarball, then 404s at codeload, so it looks exactly like a broken
// repository - and it will do so every night, forever. Reporting that as a
// failure is how a backup report teaches its reader to stop opening it.
//
// GitHub reports size in KB, and 0 for an empty repository. size alone is NOT
// proof: it can read 0 briefly after a real push. So a repository is only called
// empty when the download also failed with a not-found. Both signals must agree.
const looksEmpty = (msg) =>
  Number(repoItem.size) === 0 && /not be found|not found|404/i.test(String(msg));

const out = [];
for (const item of $input.all()) {
  const j = (item && item.json) || {};
  const raw = j.error;
  if (raw) {
    const msg = typeof raw === 'string' ? raw : (raw.message || JSON.stringify(raw));
    if (looksEmpty(msg)) {
      out.push({ json: { repo, ok: false, skipped: true, reason: 'empty - no commits to archive' } });
    } else {
      out.push({ json: { repo, ok: false, error: String(msg).slice(0, 200) } });
    }
  } else {
    out.push({ json: { repo, ok: true } });
  }
}
// A branch that emits nothing would terminate the loop silently.
if (out.length === 0) {
  out.push({ json: { repo, ok: false, error: 'no result returned for this repository' } });
}
return out;
